/**
 * Font library: the catalog in public/fonts (generated by tools/fonts/build-catalog.mjs) and
 * a registry of FontFace objects. Everything is same-origin; nothing is fetched until a font
 * is needed (the catalog itself is loaded when the picker opens or a document uses it).
 *
 * Loading model: registering a family adds one FontFace per file (variant × subset, with the
 * subset's unicode-range) to document.fonts WITHOUT loading it; `document.fonts.load()` for a
 * given variant + text then downloads only the files that variant and those characters need.
 * Variable fonts declare their weight range ("100 900"), not a single weight.
 *
 * The pure helpers (search, filter, variants, glyph coverage, favourites) take no DOM and are
 * unit-tested.
 */

export interface FontFile {
  subset: string;
  file: string;
  bytes: number;
}
export interface FontVariant {
  style: 'normal' | 'italic';
  /** Single weight, or [min, max] for a variable font. */
  weight: number | [number, number];
  format: 'woff2';
  files: FontFile[];
}
export interface FontEntry {
  id: string;
  family: string;
  categories: string[];
  source: string;
  license: { id: string; url: string | null; author: string | null; file: string };
  variable: boolean;
  subsets: string[];
  variants: FontVariant[];
  photopea: { matched: boolean; name: string | null };
  substituteFor: string | null;
}
export interface FontCatalog {
  version: number;
  families: FontEntry[];
  unicodeRanges: Record<string, string> | null;
}
export interface Category {
  id: string;
  label: string;
  count: number;
}
export type LoadState = 'idle' | 'loading' | 'ready' | 'error';

/* ------------------------------------ pure helpers ------------------------------------ */

/** Lower case, no accents, single spaces: "Ñandú  Script" → "nandu script". */
export function normalizeQuery(s: string): string {
  return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
}

/**
 * Case/accent-insensitive search plus category filter (a family matches if it has ANY of the
 * selected categories). Families whose name starts with the query come first.
 */
export function searchFonts<T extends { family: string; categories: string[] }>(list: readonly T[], query: string, cats: readonly string[] = []): T[] {
  const q = normalizeQuery(query);
  const want = new Set(cats);
  const out: { f: T; rank: number }[] = [];
  for (const f of list) {
    if (want.size && !f.categories.some((c) => want.has(c))) continue;
    if (!q) {
      out.push({ f, rank: 1 });
      continue;
    }
    const n = normalizeQuery(f.family);
    const i = n.indexOf(q);
    if (i < 0 && !n.replace(/ /g, '').includes(q.replace(/ /g, ''))) continue;
    out.push({ f, rank: i === 0 ? 0 : 1 });
  }
  return out.sort((a, b) => a.rank - b.rank).map((x) => x.f);
}

/** Weights a variant offers (a variable range is offered in steps of 100). */
export function variantWeights(v: FontVariant): number[] {
  if (!Array.isArray(v.weight)) return [v.weight];
  const [lo, hi] = v.weight;
  const out: number[] = [];
  for (let w = Math.ceil(lo / 100) * 100; w <= hi; w += 100) out.push(w);
  if (!out.length) out.push(lo);
  return out;
}

/** All the (weight, italic) choices of a family, in display order. */
export function variantChoices(e: Pick<FontEntry, 'variants'>): { weight: number; italic: boolean }[] {
  const out: { weight: number; italic: boolean }[] = [];
  for (const italic of [false, true]) for (const v of e.variants.filter((x) => (x.style === 'italic') === italic)) for (const w of variantWeights(v)) out.push({ weight: w, italic });
  return out.sort((a, b) => Number(a.italic) - Number(b.italic) || a.weight - b.weight);
}

/** The variant that best matches a requested weight / style (same style first, then nearest weight). */
export function pickVariant(e: Pick<FontEntry, 'variants'>, weight: number, italic: boolean): { variant: FontVariant; weight: number; italic: boolean } | null {
  let best: { variant: FontVariant; weight: number; italic: boolean; score: number } | null = null;
  for (const v of e.variants) {
    const vi = v.style === 'italic';
    const [lo, hi] = Array.isArray(v.weight) ? v.weight : [v.weight, v.weight];
    const w = Math.min(hi, Math.max(lo, weight));
    const score = (vi === italic ? 0 : 10000) + Math.abs(w - weight);
    if (!best || score < best.score) best = { variant: v, weight: w, italic: vi, score };
  }
  return best && { variant: best.variant, weight: best.weight, italic: best.italic };
}

/** Parses a CSS unicode-range ("U+0000-00FF, U+0131, U+02??") into [lo, hi] pairs. */
export function parseUnicodeRange(s: string): [number, number][] {
  const out: [number, number][] = [];
  for (const part of s.split(',')) {
    const m = /U\+([0-9a-f?]+)(?:-([0-9a-f]+))?/i.exec(part.trim());
    if (!m) continue;
    if (m[1].includes('?')) out.push([parseInt(m[1].replace(/\?/g, '0'), 16), parseInt(m[1].replace(/\?/g, 'F'), 16)]);
    else out.push([parseInt(m[1], 16), parseInt(m[2] ?? m[1], 16)]);
  }
  return out;
}

/**
 * Characters of `text` that no subset of the family covers (they would be drawn with a
 * fallback font). Whitespace and control characters never count.
 */
export function missingChars(text: string, subsets: readonly string[], ranges: Record<string, string> | null): string[] {
  if (!ranges) return [];
  const rs = subsets.flatMap((s) => (ranges[s] ? parseUnicodeRange(ranges[s]) : []));
  if (!rs.length) return [];
  const miss = new Set<string>();
  for (const ch of text) {
    const cp = ch.codePointAt(0)!;
    if (cp < 0x21 || /\s/.test(ch)) continue;
    if (!rs.some(([lo, hi]) => cp >= lo && cp <= hi)) miss.add(ch);
  }
  return [...miss];
}

/** Reads a string list from storage; never throws (storage can be missing, full or blocked). */
export function readList(store: Pick<Storage, 'getItem'> | null, key: string, max = 200): string[] {
  try {
    const raw = store?.getItem(key);
    const v: unknown = raw ? JSON.parse(raw) : [];
    return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string').slice(0, max) : [];
  } catch {
    return [];
  }
}
export function writeList(store: Pick<Storage, 'setItem'> | null, key: string, list: readonly string[]): void {
  try {
    store?.setItem(key, JSON.stringify(list));
  } catch {
    /* storage full or blocked: the list only lives in memory */
  }
}
/** Most-recent-first list without duplicates. */
export function pushRecent(list: readonly string[], id: string, max = 12): string[] {
  return [id, ...list.filter((x) => x !== id)].slice(0, max);
}

/* ------------------------------------ catalog + registry ------------------------------------ */

const base = (): string => (typeof document !== 'undefined' ? document.baseURI : 'http://localhost/');
export const fontUrl = (rel: string): string => new URL(`fonts/${rel}`, base()).href;

let catalogP: Promise<FontCatalog | null> | null = null;
let catalog: FontCatalog | null = null;
let categories: Category[] = [];
const byId = new Map<string, FontEntry>();
const byFamily = new Map<string, FontEntry>();

/** Loads the catalog once (null when it is not served, e.g. the single-file build). */
export function loadCatalog(): Promise<FontCatalog | null> {
  catalogP ??= (async () => {
    try {
      const [r, rc] = await Promise.all([fetch(fontUrl('catalog/fonts.json')), fetch(fontUrl('catalog/categories.json'))]);
      if (!r.ok) throw new Error(String(r.status));
      const c = (await r.json()) as FontCatalog;
      if (!c || !Array.isArray(c.families)) throw new Error('catálogo no válido');
      catalog = c;
      for (const f of c.families) {
        byId.set(f.id, f);
        byFamily.set(f.family.toLowerCase(), f);
      }
      categories = rc.ok ? ((await rc.json()) as Category[]) : [];
      return c;
    } catch (err) {
      console.warn('[fuentes] catálogo no disponible:', err);
      catalogP = null; // allow a retry later
      return null;
    }
  })();
  return catalogP;
}
export const catalogLoaded = (): FontCatalog | null => catalog;
export const catalogCategories = (): Category[] => categories;
/** Entry by id, or by family name for documents saved before fontId existed. */
export function findEntry(fontId: string | undefined, family: string): FontEntry | null {
  return (fontId ? byId.get(fontId) : undefined) ?? byFamily.get(family.toLowerCase()) ?? null;
}

const registered = new Set<string>();
const states = new Map<string, LoadState>();
const pending = new Map<string, Promise<boolean>>();
const listeners = new Set<(id: string, s: LoadState) => void>();
export const onFontState = (fn: (id: string, s: LoadState) => void): (() => void) => {
  listeners.add(fn);
  return () => listeners.delete(fn);
};
const setState = (id: string, s: LoadState): void => {
  states.set(id, s);
  for (const fn of listeners) fn(id, s);
};
export const fontState = (id: string): LoadState => states.get(id) ?? 'idle';
/** Families whose faces this module must not register (already bundled by fonts.ts). */
const skip = new Set<string>();
export function setBundledFamilies(names: readonly string[]): void {
  for (const n of names) skip.add(n.toLowerCase());
}

/** Adds the family's faces to document.fonts (no download yet). */
function register(e: FontEntry): void {
  if (registered.has(e.id) || skip.has(e.family.toLowerCase())) return;
  registered.add(e.id);
  for (const v of e.variants) {
    const weight = Array.isArray(v.weight) ? `${v.weight[0]} ${v.weight[1]}` : String(v.weight);
    for (const f of v.files) {
      const range = catalog?.unicodeRanges?.[f.subset];
      const face = new FontFace(e.family, `url("${fontUrl(f.file)}") format("woff2")`, { weight, style: v.style, display: 'swap', ...(range ? { unicodeRange: range } : {}) });
      document.fonts.add(face);
    }
  }
}

/**
 * Loads one variant of a family for the given text (only the files those characters need).
 * Deduplicated per (family, variant); a failed load can be retried by calling again.
 */
export function loadVariant(e: FontEntry, weight: number, italic: boolean, text = 'AaÑñ'): Promise<boolean> {
  register(e);
  const pick = pickVariant(e, weight, italic);
  const w = pick?.weight ?? weight;
  const it = pick?.italic ?? italic;
  const key = `${e.id}|${w}|${it}|${text.length > 40 ? text.slice(0, 40) : text}`;
  const p0 = pending.get(key);
  if (p0) return p0;
  if (fontState(e.id) !== 'ready') setState(e.id, 'loading');
  const css = `${it ? 'italic ' : ''}${w} 32px "${e.family}"`;
  const p = document.fonts
    .load(css, text || 'A')
    .then((faces) => {
      const ok = faces.length > 0 || skip.has(e.family.toLowerCase());
      if (!ok) throw new Error('sin caras cargadas');
      setState(e.id, 'ready');
      return true;
    })
    .catch((err) => {
      console.warn(`[fuentes] no se pudo cargar «${e.family}» (${w}${it ? ' cursiva' : ''}):`, err);
      pending.delete(key); // retry on the next request
      setState(e.id, 'error');
      return false;
    });
  pending.set(key, p);
  return p;
}

/** Small FIFO with a concurrency limit for preview loads (visible rows of the picker). */
export class LoadQueue {
  private q: (() => Promise<unknown>)[] = [];
  private active = 0;
  constructor(private readonly limit = 4) {}
  push(job: () => Promise<unknown>): void {
    this.q.push(job);
    this.pump();
  }
  clear(): void {
    this.q = [];
  }
  private pump(): void {
    while (this.active < this.limit && this.q.length) {
      const job = this.q.shift()!;
      this.active++;
      void job().finally(() => {
        this.active--;
        this.pump();
      });
    }
  }
}
